class KodiBuiltinCommand{const KodiBuiltinCommand({required this.raw,required this.name,required this.arguments});final String raw,name;final List<String> arguments;String get normalizedName=>name.trim().toLowerCase();String?argument(int i)=>i<0||i>=arguments.length?null:arguments[i];bool get isEmpty=>name.trim().isEmpty;factory KodiBuiltinCommand.parse(String source){final raw=source.trim();if(raw.isEmpty)return const KodiBuiltinCommand(raw:'',name:'',arguments:[]);final open=raw.indexOf('(');if(open<0)return KodiBuiltinCommand(raw:raw,name:raw,arguments:const []);final close=_matchingClose(raw,open);final body=close>open?raw.substring(open+1,close):raw.substring(open+1);return KodiBuiltinCommand(raw:raw,name:raw.substring(0,open).trim(),arguments:List.unmodifiable(_splitArguments(body).map(_unquote).map((v)=>v.trim())));}static int _matchingClose(String v,int open){var depth=0;String? quote;var escaped=false;for(var i=open;i<v.length;i++){final c=v[i];if(escaped){escaped=false;continue;}if(c=='\\'){escaped=true;continue;}if(quote!=null){if(c==quote)quote=null;continue;}if(c=='"'||c=="'"){quote=c;continue;}if(c=='(')depth++;else if(c==')'){depth--;if(depth==0)return i;}}return -1;}static List<String>_splitArguments(String v){if(v.trim().isEmpty)return const [];final r=<String>[],b=StringBuffer();var depth=0;String? quote;var escaped=false;void finish(){r.add(b.toString());b.clear();}for(var i=0;i<v.length;i++){final c=v[i];if(escaped){b.write(c);escaped=false;continue;}if(c=='\\'){b.write(c);escaped=true;continue;}if(quote!=null){b.write(c);if(c==quote)quote=null;continue;}if(c=='"'||c=="'"){quote=c;b.write(c);continue;}if(c=='('){depth++;b.write(c);continue;}if(c==')'){if(depth>0)depth--;b.write(c);continue;}if(c==','&&depth==0){finish();continue;}b.write(c);}finish();return r;}static String _unquote(String v){final t=v.trim();if(t.length<2)return t;final a=t[0],b=t[t.length-1];return ((a=='"'&&b=='"')||(a=="'"&&b=="'"))?t.substring(1,t.length-1):t;}}
